def strategy(history, rng):
    if not history:
        return 'D'

    opp_def = False
    for _, op in history:
        if op == 'D':
            opp_def = True
            break

    if not opp_def:
        return 'D'

    last_my, last_op = history[-1]
    if last_op == 'D':
        if last_my == 'D':
            return 'C'
        if len(history) >= 2 and history[-2][0] == 'D':
            return 'C'
        return 'D'
    else:
        return 'C'
